function minimizeXor(num1, num2) {
  // Decide x one bit at a time from the top, copying num1's bit whenever the
  // number of ones still owed can be placed in the positions below.
  const width = 31;
  let owed = num2.toString(2).split('').filter(c => c === '1').length;
  const source = num1.toString(2).padStart(width, '0');
  let built = '';
  for (let i = 0; i < width; i++) {
    const below = width - 1 - i;
    let choice = source[i] === '1' ? 1 : 0;
    if (owed - choice < 0 || owed - choice > below) choice = 1 - choice;
    built += choice;
    owed -= choice;
  }
  return parseInt(built, 2);
}

