function generate(rand, size) {
  const pick = (maxBits) => {
    const bits = 1 + Math.floor(rand() * maxBits);
    const top = 2 ** bits;
    let value = Math.floor(rand() * top);
    if (rand() < 0.25) value = top - 1;
    return Math.min(1000000000, Math.max(1, value));
  };
  const dense = () => {
    // A value with many ones: clear a few random bits from 2^29 - 1.
    let value = 2 ** 29 - 1;
    const clears = Math.floor(rand() * 6);
    for (let i = 0; i < clears; i++) value &= ~(1 << Math.floor(rand() * 29));
    return Math.max(1, value);
  };
  if (size === 'large') {
    const num1 = rand() < 0.3 ? pick(10) : 1 + Math.floor(rand() * 1000000000);
    const num2 = rand() < 0.4 ? dense() : 1 + Math.floor(rand() * 1000000000);
    return [num1, num2];
  }
  return [pick(7), pick(7)];
}
